import{_ as t,o as a,c as d,ag as s}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Modeles","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models.md","filePath":"fr/guide/models.md"}'),o={name:"fr/guide/models.md"};function l(r,e,i,n,m,c){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="modeles" tabindex="-1">Modeles <a class="header-anchor" href="#modeles" aria-label="Permalink to &quot;Modeles&quot;">​</a></h1><p>La page Modeles est un navigateur pour tous les modeles installes dans votre instance Ollama locale, avec des metadonnees detaillees et la detection des capacites.</p><p><strong>Element de la barre laterale :</strong> Modeles <strong>Route :</strong> <code>/settings?tab=models</code></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page Modeles (accessible via l&#39;onglet Parametres &gt; Modeles) affiche une carte ou une liste pour chaque modele installe avec les informations essentielles en un coup d&#39;oeil.</p><h2 id="details-des-modeles" tabindex="-1">Details des modeles <a class="header-anchor" href="#details-des-modeles" aria-label="Permalink to &quot;Details des modeles&quot;">​</a></h2><p>Chaque carte de modele affiche :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Description</th></tr></thead><tbody><tr><td><strong>Nom</strong></td><td>Identifiant du modele (par ex., <code>llama3.2:latest</code>)</td></tr><tr><td><strong>Nombre de parametres</strong></td><td>Nombre de parametres (par ex., 3B, 7B, 70B)</td></tr><tr><td><strong>Quantification</strong></td><td>Niveau de compression (par ex., Q4_0, Q8_0, F16)</td></tr><tr><td><strong>Famille</strong></td><td>Famille du modele (par ex., llama, mistral, gemma)</td></tr><tr><td><strong>Format</strong></td><td>Format du modele (par ex., gguf)</td></tr></tbody></table><h2 id="diagrammes-d-architecture" tabindex="-1">Diagrammes d&#39;architecture <a class="header-anchor" href="#diagrammes-d-architecture" aria-label="Permalink to &quot;Diagrammes d&#39;architecture&quot;">​</a></h2><p>Cliquez sur un modele pour voir un diagramme d&#39;architecture montrant la structure interne du modele -- nombre de couches, tetes d&#39;attention, dimensions d&#39;embedding, et plus encore. Ces informations sont extraites des metadonnees du modele fournies par Ollama.</p><h2 id="detection-des-capacites" tabindex="-1">Detection des capacites <a class="header-anchor" href="#detection-des-capacites" aria-label="Permalink to &quot;Detection des capacites&quot;">​</a></h2><p>LLMxRay detecte automatiquement ce que chaque modele peut faire :</p><table tabindex="0"><thead><tr><th>Capacite</th><th>Comment elle est detectee</th><th>Effet sur l&#39;interface</th></tr></thead><tbody><tr><td><strong>Raisonnement</strong></td><td>Patterns dans le nom du modele (par ex., <code>deepseek-r1</code>) ou capacites Ollama</td><td>Active l&#39;onglet raisonnement dans Diagnostics de Chat</td></tr><tr><td><strong>Vision</strong></td><td>Capacites Ollama ou famille du modele</td><td>Active les pieces jointes images dans le chat</td></tr><tr><td><strong>Embedding</strong></td><td>Capacites Ollama ou famille du modele</td><td>Apparait dans les selecteurs de modeles des pages Plongements et Base de Connaissances</td></tr><tr><td><strong>Appel d&#39;outils</strong></td><td>Capacites Ollama</td><td>Active l&#39;appel d&#39;outils dans le chat</td></tr></tbody></table><p>Les modeles ne prenant en charge que les embeddings sont automatiquement filtres des selecteurs de modeles de chat.</p><h2 id="catalogue-de-modeles" tabindex="-1">Catalogue de modeles <a class="header-anchor" href="#catalogue-de-modeles" aria-label="Permalink to &quot;Catalogue de modeles&quot;">​</a></h2><p>Le catalogue offre une vue organisee des modeles disponibles avec des tableaux comparatifs, vous aidant a choisir le modele adapte a votre cas d&#39;utilisation.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Compromis de quantification</strong> -- Une quantification basse (Q4) utilise moins de RAM mais reduit legerement la qualite. Q8 et F16 offrent une meilleure qualite mais necessitent plus de memoire.</li><li><strong>Telecharger d&#39;autres modeles</strong> depuis le terminal : <code>ollama pull &lt;nom-du-modele&gt;</code></li><li>La detection des capacites adapte l&#39;ensemble de l&#39;interface -- vous n&#39;avez rien a configurer manuellement.</li></ul>',18)])])}const h=t(o,[["render",l]]);export{p as __pageData,h as default};
